  reason = 'STOP 0 A – SoC ' + currentBatSoc + ' % >= cíl ' + effectiveTargetSoc + ' % (ochrana baterie)';
} else if (priceModeCode === "BELOW_LIMIT" || priceModeCode === "NEGATIVE") {
  targetA = 50; // Nabíjení 50A akumulátoru
  reason = 'AUTO NABÍJET 50 A (STAV ' + (priceModeCode === "NEGATIVE" ? '3: Záporná cena' : '2: Cena pod limitem') + ' ' + p.final.toFixed(2) + ' <= limit ' + chargeLimit.toFixed(2) + ' Kč/kWh)';
} else {
  targetA = 0;
  reason = 'STOP 0 A (STAV 1: Kladná cena nad limitem ' + Number(p.final).toFixed(2) + ' > limit ' + chargeLimit.toFixed(2) + ' Kč/kWh)';
}

global.set('solax_charge_decision',{targetA,reason,priceKcKwh:p.final,priceKnown:p.known,chargeLimitKcKwh:chargeLimit,cheap,cheapPriceBatteryMode,cheapPriceBatteryModeLabel:cheapPriceBatteryModeLabels[cheapPriceBatteryMode],solaxPriceSelected,soc:currentBatSoc,targetSoc:effectiveTargetSoc,controlMode:manualMode,manualOverride:manual,batteryVoltageV:batteryV,ts:new Date().toISOString()});

// EEPROM ochrana
const eepromHeartbeat = 300000;
const targetChanged = state.lastTargetA !== targetA;
const heartbeatExpired = !state.lastWrittenAt || (now - state.lastWrittenAt) >= eepromHeartbeat;

if (!targetChanged && !heartbeatExpired) {
  node.status({ fill: targetA > 0 ? 'green' : 'grey', shape: 'dot',
    text: (targetA > 0 ? 'NABÍJET ' : 'STOP ') + targetA + ' A · beze změny' });
  return null;
}

const password = num(global.get('solax_installer_password') ?? 2014, 2014);
const unit = Math.round(clamp(num(global.get('solax_unit_id') ?? 1, 1), 0, 255));
const seed = (now % 50000) + 100;

// Škála R36: 1 A = 100 (0.01 A rozlišení)
// Pro 50 A -> hodnota 5000!
// Pro 0 A -> hodnota 0
const r36value = Math.round(clamp(targetA * 100, 0, 5000));

// Sekvence:
// Krok 1: Heslo R0 = 2014
// Krok 2: Nabíjecí proud R36 = targetA * 100 (např. 50 A -> 5000)
// Krok 3: Readback R36 (ověření zápisu)
const queue = [
  { step: 1, type: 'write', tid: seed, unit, address: 0, value: password,
    label: 'Heslo R0=' + password },
  { step: 2, type: 'write', tid: seed + 1, unit, address: 36, value: r36value,
    label: 'Nabíjecí proud R36=' + r36value + ' (' + targetA + ' A)' },
  { step: 3, type: 'read', tid: seed + 2, unit, address: 36, count: 1,
    expectedRaw: r36value, expectedA: targetA, label: 'Readback R36' }
];

state = {
  busy: true,
  startedAt: now,
  stepIndex: 0,
  queue,
  expectedTargetA: targetA,
  expectedR36: r36value,
  batteryVoltageV: batteryV,
  reason,
  manualSeq
};
flow.set('solaxControlV160', state);

const firstItem = queue[0];
msg.payload = buildModbusFrame(firstItem);
msg._solaxStep = firstItem;
msg._solaxStepIndex = 0;
node.status({ fill: 'blue', shape: 'dot',
  text: 'Krok 1/' + queue.length + ' → ' + firstItem.label });
return msg;

// v160 SolaX Step Parser (R36 škála: 1 A = 100)

function fail(text) {
  let state = flow.get('solaxControlV160') || {};
  state.busy = false;
  state.queue = [];
  state.retryNotBefore = Date.now() + 4000;
  flow.set('solaxControlV160', state);
  global.set('solax_modbus_last_error', { text, ts: new Date().toISOString() });
  const events = global.get('solax_modbus_events') || [];
  events.unshift({ ts: new Date().toISOString(), event: 'ERROR', text, ok: false });
  if (events.length > 30) events.length = 30;
  global.set('solax_modbus_events', events);
  node.status({ fill: 'red', shape: 'ring', text: text.slice(0, 100) });
  return [null, null];
}

function buildModbusFrame(item) {
  const b = Buffer.alloc(12);
  b.writeUInt16BE(item.tid, 0);
  b.writeUInt16BE(0, 2);
  b.writeUInt16BE(6, 4);
  b[6] = item.unit;
  if (item.type === 'write') {
    b[7] = 6;
    b.writeUInt16BE(item.address, 8);
    b.writeUInt16BE(item.value, 10);
  } else {
    b[7] = 3;
    b.writeUInt16BE(item.address, 8);
    b.writeUInt16BE(item.count || 1, 10);
  }
  return b;
}

const b = Buffer.isBuffer(msg.payload) ? msg.payload : Buffer.from(msg.payload || []);
if (b.length < 8) return fail('Krátká odpověď (' + b.length + ' B)');

const frames = [];
let offset = 0;
while (offset + 6 <= b.length) {
  const tid = b.readUInt16BE(offset);
  const length = b.readUInt16BE(offset + 4);
  const total = 6 + length;
  if (offset + total > b.length) break;
  frames.push({ tid, unit: b[offset + 6], fc: b[offset + 7], data: b.slice(offset + 8, offset + total) });
  offset += total;
}
if (!frames.length) return fail('Žádný Modbus rámec v odpovědi');

let state = flow.get('solaxControlV160') || {};
const queue = state.queue || [];
const stepIdx = Number(msg._solaxStepIndex !== undefined ? msg._solaxStepIndex : state.stepIndex || 0);
const curItem = queue[stepIdx] || msg._solaxStep || {};

let matched = null;
for (const f of frames) { if (curItem.tid !== undefined && f.tid === curItem.tid) { matched = f; break; } }
if (!matched) {
  for (const f of frames) {
    if (curItem.type === 'write' && f.fc === 6 && f.data.length >= 4 && f.data.readUInt16BE(0) === curItem.address) { matched = f; break; }
    if (curItem.type === 'read' && f.fc === 3) { matched = f; break; }
  }
}
if (!matched) matched = frames[frames.length - 1];
if ((matched.fc & 0x80) !== 0) return fail('Modbus výjimka u kroku ' + (stepIdx + 1) + ' (FC=0x' + matched.fc.toString(16) + ')');

const nowIso = new Date().toISOString();
const events = global.get('solax_modbus_events') || [];

if (curItem.type === 'write') {
  if (matched.fc !== 6 || matched.data.length < 4) return fail('Neplatná FC6 odpověď');
  const respAddr = matched.data.readUInt16BE(0);
  const respVal = matched.data.readUInt16BE(2);
  if (respAddr !== curItem.address) return fail('Neshoda adresy: zapsáno R' + curItem.address + ', vráceno R' + respAddr);

  events.unshift({ ts: nowIso, event: 'WRITE_OK', address: curItem.address, value: respVal, text: curItem.label, ok: true });
  if (events.length > 30) events.length = 30;
  global.set('solax_modbus_events', events);

} else if (curItem.type === 'read') {
  if (matched.fc !== 3 || matched.data.length < 3) return fail('Neplatná FC3 odpověď');
  const rawValue = matched.data.readUInt16BE(1);
  const targetA = Number(state.expectedTargetA);
  const expectedRaw = Number(state.expectedR36);

  // Škála R36: 1 A = 100
  const readbackA = Number((rawValue / 100).toFixed(1));

  // Shoda: tolerance ±1 A (±100 raw)
  const match = (targetA === 0) ? (rawValue <= 200) : (Math.abs(rawValue - expectedRaw) <= 200);

  state.busy = false;
  state.queue = [];
  state.stepIndex = 0;
  state.retryNotBefore = 0;
  state.lastTargetA = targetA;
  state.lastWrittenAt = Date.now();
  flow.set('solaxControlV160', state);

  global.set('solax_modbus_last_error', match ? null : { text: 'Neshoda R36: cíl ' + targetA + ' A (' + expectedRaw + '), načteno ' + readbackA + ' A (' + rawValue + ')', ts: nowIso });
  global.set('solax_modbus_last_verify', {
    ok: match, match, register: 36, rawValue,
    readbackA, expectedRaw, expectedA: targetA, ts: nowIso
  });

  const stateText = targetA > 0 ? ('CHARGING_' + targetA + 'A') : 'STOP_0A';
  global.set('solax_control_status', {
    state: stateText, endpoint: '192.168.0.155:502',
    targetA, readbackA, readbackRaw: rawValue, verified: match,
    reason: state.reason, ts: nowIso
  });

  const eventText = match
    ? (targetA > 0 ? 'NABÍJENÍ ' + targetA + ' A (R36=' + rawValue + ' -> ' + readbackA + ' A)' : 'STOP 0 A (R36=' + rawValue + ')')
    : 'NESHODA R36: cíl ' + expectedRaw + ', naměřeno ' + rawValue;
  events.unshift({ ts: nowIso, event: match ? 'READBACK_OK' : 'READBACK_FAIL', address: 36, value: rawValue, text: eventText, ok: match });
  if (events.length > 30) events.length = 30;
  global.set('solax_modbus_events', events);

  node.status({ fill: match ? (targetA > 0 ? 'green' : 'grey') : 'red', shape: 'dot',
    text: (match ? 'OK ' : 'FAIL ') + targetA + ' A (' + rawValue + ')' });
  return [null, { payload: { event: 'verified', targetA, readbackA, rawValue, match } }];
}

const nextIdx = stepIdx + 1;
if (nextIdx < queue.length) {
  state.stepIndex = nextIdx;
  flow.set('solaxControlV160', state);
  const nextItem = queue[nextIdx];
  const nextMsg = { payload: buildModbusFrame(nextItem), _solaxStep: nextItem, _solaxStepIndex: nextIdx };
  node.status({ fill: 'blue', shape: 'dot', text: 'Krok ' + (nextIdx + 1) + '/' + queue.length + ' → ' + nextItem.label });
  return [nextMsg, null];
}
return [null, null];

// Ignorovat zprávy od samotného bota
if (msg.author && msg.author.bot) return null;

const text = String(msg.payload || '').trim().toLowerCase();
let reply = null;
let action = null;
let newSettings = null;

if (text === '!status') {
    const soc = global.get('cerbo_batterySoc') || global.get('solax_last_battery_soc') || '?';
    const grid = global.get('cerbo_acGridPower') || 0;
    const pv = (global.get('cerbo_pvPower') || 0) + (global.get('solax_pvPower') || 0);
    const price = global.get('currentPriceFinalKcKwh') || '?';

    reply = `📊 **Aktuální stav systému:**\n🔋 Baterie: ${Number(soc).toFixed(1)} %\n☀️ Výroba FV: ${Number(pv).toFixed(0)} W\n🔌 Síť: ${Number(grid).toFixed(0)} W\n💰 Cena: ${Number(price).toFixed(4)} Kč/kWh`;
} 
else if (text === '!bms') {
    const minC = global.get('cerbo_jkMinCellV') || '?';
    const maxC = global.get('cerbo_jkMaxCellV') || '?';
    const delta = global.get('cerbo_jkCellDeltaMv') || '?';
    const temp = global.get('cerbo_batteryTempC') || '?';
    reply = `🔋 **BMS Detaily:**\n🌡️ Teplota: ${temp} °C\n⚡ Články: ${minC} V / ${maxC} V (Δ ${delta} mV)`;
}
else if (text === '!auto') {
    action = 'auto_on';
    reply = '✅ Přepínám Victron do režimu **AUTO**';
}
else if (text === '!inv') {
    action = 'inverter_only';
    reply = '✅ Přepínám Victron do režimu **INVERTER ONLY**';
}
else if (text === '!ess') {
    action = 'ess_on';
    reply = '✅ Přepínám Victron do režimu **ESS**';
}
else if (text === '!stop') {
    action = 'force_charge_off';
    reply = '🛑 Zastavuji nabíjení (Nouzový STOP)';
}
else if (text.startsWith('!rele1 ')) {
    const cmd = text.split(' ')[1];
    if (['on', 'off', 'auto'].includes(cmd)) {
        action = 'relay1_' + cmd;
        reply = `🔌 Relé 1 (Wattrouter) nastaveno na: **${cmd.toUpperCase()}**`;
    }
}
else if (text.startsWith('!rele2 ')) {
    const cmd = text.split(' ')[1];
    if (['on', 'off', 'auto'].includes(cmd)) {
        action = 'relay2_' + cmd;
        reply = `🔌 Relé 2 (Bojler) nastaveno na: **${cmd.toUpperCase()}**`;
    }
}
else if (text.startsWith('!limit ')) {
    const num = Number(text.split(' ')[1].replace(',', '.'));
    if (Number.isFinite(num)) {
        newSettings = { chargeBelowFinalPriceKcKwh: num };
        reply = `💰 Limit pro nabíjení **Victronu** změněn na: **${num.toFixed(2)} Kč/kWh**`;
    }
}
else if (text.startsWith('!solaxlimit ')) {
    const num = Number(text.split(' ')[1].replace(',', '.'));
    if (Number.isFinite(num)) {
        newSettings = { solaxChargeBelowFinalPriceKcKwh: num };
        reply = `💰 Limit pro nabíjení **SolaXu** změněn na: **${num.toFixed(2)} Kč/kWh**`;
    }
}
else if (text === '!graf') {
    const prices = global.get('enerspotPrices15') || [];
    if (prices.length > 0) {
        const labels = prices.slice(0, 24).map(p => p.time);
        const data = prices.slice(0, 24).map(p => p.finalKcKwh || p.final);

        const chartConfig = {
            type: 'line',
            data: {
                labels: labels,
                datasets: [{
                    label: 'Cena Kč/kWh',
                    data: data,
                    borderColor: 'rgb(59, 130, 246)',
                    backgroundColor: 'rgba(59, 130, 246, 0.5)',
                    fill: true
                }]
            }
        };
        const url = 'https://quickchart.io/chart?c=' + encodeURIComponent(JSON.stringify(chartConfig));
        reply = `📈 **Graf dnešních cen:**\n${url}`;
    } else {
        reply = '❌ Nemám data o cenách.';
    }
}
else if (text.startsWith('!')) {
    reply = `❓ Neznámý příkaz. Dostupné příkazy:\n` +
            `**!status** - Základní přehled\n` +
            `**!bms** - Detaily baterie a článků\n` +
            `**!graf** - Graf dnešních cen\n` +
            `**!limit <číslo>** - Změní limit nákupu pro Victron (např. !limit 1.50)\n` +
            `**!solaxlimit <číslo>** - Změní limit pro SolaX\n` +
            `**!rele1 <on/off/auto>** - Ovladač Wattrouteru\n` +
            `**!rele2 <on/off/auto>** - Ovladač Bojleru\n` +
            `**!auto** | **!inv** | **!ess** | **!stop** - Režimy Victronu`;
}

const msgs = [];

// Output 1: Reply to Discord
if (reply) {
    msgs.push({ payload: reply });
} else {
    msgs.push(null);
}

// Output 2: Action to Dashboard command handler
if (action || newSettings) {
    let outCmd = {};
    if (action) outCmd.action = action;
    if (newSettings) {
        outCmd.action = 'save_settings';
        outCmd.settings = newSettings;
    }
    msgs.push({ payload: outCmd });
} else {
    msgs.push(null);
}

return msgs;

const gridConnected = global.get('cerbo_vebusActiveInConnected');
const loadPower = global.get('cerbo_acGridPower') || 0; // Wait, consumption is cerbo_acConsumptionPower
const consumption = global.get('cerbo_acConsumptionPower') || 0;

let lastGrid = context.get('lastGrid');
let lastOverload = context.get('lastOverload') || false;
let msgOut = null;

if (lastGrid !== undefined && gridConnected !== undefined) {
    if (lastGrid === 1 && gridConnected === 0) {
        msgOut = { payload: "⚠️ **POZOR:** Výpadek sítě! AC Vstup je odpojen." };
    } else if (lastGrid === 0 && gridConnected === 1) {
        msgOut = { payload: "✅ **INFO:** Síť byla obnovena. AC Vstup připojen." };
    }
}
context.set('lastGrid', gridConnected);

const isOverloaded = consumption > 6500;
if (isOverloaded && !lastOverload) {
    if(!msgOut) msgOut = {payload: ""};
    msgOut.payload += "\n⚠️ **VAROVÁNÍ:** Velké zatížení domu! Spotřeba je " + Number(consumption).toFixed(0) + " W.";
    context.set('lastOverload', true);
} else if (!isOverloaded && lastOverload) {
    context.set('lastOverload', false);
}

if (msgOut && msgOut.payload) {
    return msgOut;
}
return null;

const yieldKwh = global.get('cerbo_solarYieldToday') || 0;
const soldKwh = global.get('cerbo_soldEnergyToday') || 0;
const soldKc = global.get('cerbo_soldEnergyKcToday') || 0;
const r2Kwh = global.get('cerbo_r2EnergyTodayKwh') || 0;

msg.payload = `📊 **Denní shrnutí (Půlnoc):**\n` +
`☀️ Vyrobeno: ${Number(yieldKwh).toFixed(2)} kWh\n` +
`🔌 Prodáno do sítě: ${Number(soldKwh).toFixed(2)} kWh\n` +
`💸 Zisk z prodeje: ${Number(soldKc).toFixed(2)} Kč\n` +
`🔥 Do bojleru (R2): ${Number(r2Kwh).toFixed(2)} kWh`;

return msg;
